window.GULF_CONFIG={"extra":{"abudhabi":[],"dubai":[{"id":"DU-001","edition":"dubai","kind":"practice-setting","replaces":null,"domain":"Nursing Management and Leadership","subdomain":"Scope and competence","stem":"A DHA-licensed nurse is allocated a nonurgent procedure that the nurse has never been trained to perform. What is the best response?","options":[{"label":"A","text":"Ask the patient to accept the additional risk."},{"label":"B","text":"Explain the competence gap and arrange a suitably qualified practitioner."},{"label":"C","text":"Proceed while a colleague gives instructions by telephone."},{"label":"D","text":"Perform it because a prescriber has requested it."}],"key":"B","answerText":"Explain the competence gap and arrange a suitably qualified practitioner.","rationale":"The request does not establish competence. Arranging qualified help protects the patient without abandoning care.","misconceptions":{"A":"Patient agreement cannot replace professional competence.","C":"Remote instructions do not establish assessed competence.","D":"An order does not extend the nurse’s competence."},"pearl":"DHA practice: Explain the competence gap and arrange a suitably qualified practitioner.","trap":"Remote instructions do not establish assessed competence.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Standards for Code of Ethics and Professional Conduct for Health Professionals, DHA/HRS/HPSD/ST-66, issue 1","section":"11.1.2 and 11.1.4, p.32","url":"https://dha.gov.ae/uploads/012026/Standards%20for%20Code%20of%20Ethics%20and%20Professional%20Conduct%20for%20Health%20Professionals%20V1%20202613351.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"DU-002","edition":"dubai","kind":"practice-setting","replaces":null,"domain":"Nursing Management and Leadership","subdomain":"Delegation checks","stem":"A nurse supervising care in a DHA-licensed facility plans to delegate a routine clinical task. Which check is essential?","options":[{"label":"A","text":"Choose the worker who agrees to accept responsibility."},{"label":"B","text":"Confirm that the task fits the worker’s authorized role and demonstrated competence."},{"label":"C","text":"Choose the worker who has the lightest workload."},{"label":"D","text":"Use the worker who has observed the task most often."}],"key":"B","answerText":"Confirm that the task fits the worker’s authorized role and demonstrated competence.","rationale":"Willingness and availability do not establish authority or ability. Delegation must fit the person and the task.","misconceptions":{"A":"Agreement does not create authority to perform a task.","C":"Workload matters only after role and ability are established.","D":"Observation alone does not establish competence."},"pearl":"DHA practice: Confirm that the task fits the worker’s authorized role and demonstrated competence.","trap":"Workload matters only after role and ability are established.","difficulty":"Medium","judgment":"Generate Solutions","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Standards for Code of Ethics and Professional Conduct for Health Professionals, DHA/HRS/HPSD/ST-66, issue 1","section":"14.1.1 and 14.1.9, pp.36–37","url":"https://dha.gov.ae/uploads/012026/Standards%20for%20Code%20of%20Ethics%20and%20Professional%20Conduct%20for%20Health%20Professionals%20V1%20202613351.pdf","accessed":"2026-10-25"},"review":{"panel":"FIXED","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Exact replacements applied: judgment. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"DU-003","edition":"dubai","kind":"practice-setting","replaces":null,"domain":"Nursing Management and Leadership","subdomain":"Delegation follow-up","stem":"In Dubai, a nurse delegates an authorized task to a competent team member. Which follow-up is most appropriate?","options":[{"label":"A","text":"Remove the task from handover because it was delegated."},{"label":"B","text":"Check the reported outcome and provide supervision matched to the task."},{"label":"C","text":"Review the outcome only if the patient makes a complaint."},{"label":"D","text":"Assume completion because the worker accepted the task."}],"key":"B","answerText":"Check the reported outcome and provide supervision matched to the task.","rationale":"Delegation does not end the need for oversight. Outcome review helps identify care that needs adjustment.","misconceptions":{"A":"Delegated care can remain relevant at handover.","C":"Waiting for a complaint misses earlier signs of incomplete care.","D":"Acceptance is not evidence of a safe outcome."},"pearl":"DHA practice: Check the reported outcome and provide supervision matched to the task.","trap":"Waiting for a complaint misses earlier signs of incomplete care.","difficulty":"Medium","judgment":"Evaluate Outcomes","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Standards for Code of Ethics and Professional Conduct for Health Professionals, DHA/HRS/HPSD/ST-66, issue 1","section":"14.1.2 and 14.1.13, pp.36–37","url":"https://dha.gov.ae/uploads/012026/Standards%20for%20Code%20of%20Ethics%20and%20Professional%20Conduct%20for%20Health%20Professionals%20V1%20202613351.pdf","accessed":"2026-10-25"},"review":{"panel":"FIXED","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Exact replacements applied: judgment. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"DU-004","edition":"dubai","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Consent and understanding","stem":"In a DHA-licensed unit, a patient awaiting an elective procedure cannot explain what the procedure involves despite a signed form. What should the nurse do first?","options":[{"label":"A","text":"Ask a relative to confirm that the procedure is acceptable."},{"label":"B","text":"Repeat the procedure name and request another signature."},{"label":"C","text":"Pause preparation and arrange an understandable explanation before consent is confirmed."},{"label":"D","text":"Continue because the signed form is already in the record."}],"key":"C","answerText":"Pause preparation and arrange an understandable explanation before consent is confirmed.","rationale":"A signature alone does not show informed agreement. The misunderstanding must be addressed before the elective procedure proceeds.","misconceptions":{"A":"A relative’s agreement does not replace the capable patient’s consent.","B":"Repeating a name does not explain the procedure.","D":"A form does not resolve the stated misunderstanding."},"pearl":"DHA practice: Pause preparation and arrange an understandable explanation before consent is confirmed.","trap":"A form does not resolve the stated misunderstanding.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Standards for Code of Ethics and Professional Conduct for Health Professionals, DHA/HRS/HPSD/ST-66, issue 1","section":"8.2.1–8.2.6, pp.17–18","url":"https://dha.gov.ae/uploads/012026/Standards%20for%20Code%20of%20Ethics%20and%20Professional%20Conduct%20for%20Health%20Professionals%20V1%20202613351.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"DU-005","edition":"dubai","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Patient advocacy","stem":"A capable adult in Dubai asks to discuss an alternative treatment. A family member prefers the proposed plan. What should the nurse do?","options":[{"label":"A","text":"Support the patient in discussing options with the treating clinician."},{"label":"B","text":"Ask the family to decide which option will be discussed."},{"label":"C","text":"Discourage further questions because a plan is documented."},{"label":"D","text":"Ask the patient to decide without further information."}],"key":"A","answerText":"Support the patient in discussing options with the treating clinician.","rationale":"Care should support the patient’s informed participation. Family involvement should not prevent the patient from receiving information.","misconceptions":{"B":"Family preference does not displace a capable adult’s voice.","C":"Documentation does not end the right to ask questions.","D":"A meaningful choice requires adequate information."},"pearl":"DHA practice: Support the patient in discussing options with the treating clinician.","trap":"Family preference does not displace a capable adult’s voice.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Standards for Code of Ethics and Professional Conduct for Health Professionals, DHA/HRS/HPSD/ST-66, issue 1","section":"8.1.3 and 8.2.2, pp.15–17","url":"https://dha.gov.ae/uploads/012026/Standards%20for%20Code%20of%20Ethics%20and%20Professional%20Conduct%20for%20Health%20Professionals%20V1%20202613351.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"DU-006","edition":"dubai","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Confidentiality","stem":"In a Dubai clinic, a caller requests an adult patient’s test results and claims to be a relative. Permission to disclose has not been established. What is best?","options":[{"label":"A","text":"Give the results if the person knows the patient’s birth date."},{"label":"B","text":"Ask another visitor to confirm the relationship."},{"label":"C","text":"Verify identity and the authority to receive information before disclosure."},{"label":"D","text":"Share only the abnormal results to limit disclosure."}],"key":"C","answerText":"Verify identity and the authority to receive information before disclosure.","rationale":"The request alone does not authorize disclosure. Identity and a valid basis for access must both be established.","misconceptions":{"A":"A known personal detail does not establish authority.","B":"Another visitor cannot establish consent or legal authority.","D":"Selected results are still confidential information."},"pearl":"DHA practice: Verify identity and the authority to receive information before disclosure.","trap":"Selected results are still confidential information.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Standards for Code of Ethics and Professional Conduct for Health Professionals, DHA/HRS/HPSD/ST-66, issue 1","section":"9.1.1 and 9.1.5, pp.20–21","url":"https://dha.gov.ae/uploads/012026/Standards%20for%20Code%20of%20Ethics%20and%20Professional%20Conduct%20for%20Health%20Professionals%20V1%20202613351.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"DU-007","edition":"dubai","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Privacy and dignity","stem":"In a Dubai ward, a stable patient’s sensitive history is being discussed within hearing of unrelated visitors. What is the best action?","options":[{"label":"A","text":"Move the conversation to a private setting with the patient’s agreement."},{"label":"B","text":"Continue quietly while using the patient’s room number."},{"label":"C","text":"Ask visitors to ignore the conversation and continue."},{"label":"D","text":"Omit the patient’s name but discuss the full history."}],"key":"A","answerText":"Move the conversation to a private setting with the patient’s agreement.","rationale":"Avoidable exposure of personal information should be reduced. Omitting a name does not make an identifiable bedside conversation private.","misconceptions":{"B":"Room context can still identify the patient.","C":"A request to ignore information does not protect privacy.","D":"The surroundings can identify the person without a name."},"pearl":"DHA practice: Move the conversation to a private setting with the patient’s agreement.","trap":"Room context can still identify the patient.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Standards for Code of Ethics and Professional Conduct for Health Professionals, DHA/HRS/HPSD/ST-66, issue 1","section":"9.1.8, p.21","url":"https://dha.gov.ae/uploads/012026/Standards%20for%20Code%20of%20Ethics%20and%20Professional%20Conduct%20for%20Health%20Professionals%20V1%20202613351.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"DU-008","edition":"dubai","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Respectful cultural care","stem":"A stable patient in a DHA-licensed unit requests a same-gender practitioner for an intimate examination. What is the best initial response?","options":[{"label":"A","text":"Ask a family member to persuade the patient to withdraw it."},{"label":"B","text":"Cancel all planned care until a same-gender team is available."},{"label":"C","text":"Explore the preference and arrange suitable care where feasible without delaying urgent needs."},{"label":"D","text":"Assume the request applies to every future procedure."}],"key":"C","answerText":"Explore the preference and arrange suitable care where feasible without delaying urgent needs.","rationale":"Preferences should be discussed individually and respected where feasible. The nurse must also account for the urgency of care.","misconceptions":{"A":"Pressure from family can undermine the patient’s choice.","B":"A blanket cancellation may cause unnecessary delay.","D":"An individual preference must not be generalized without discussion."},"pearl":"DHA practice: Explore the preference and arrange suitable care where feasible without delaying urgent needs.","trap":"An individual preference must not be generalized without discussion.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Standards for Code of Ethics and Professional Conduct for Health Professionals, DHA/HRS/HPSD/ST-66, issue 1","section":"8.1.7, p.16","url":"https://dha.gov.ae/uploads/012026/Standards%20for%20Code%20of%20Ethics%20and%20Professional%20Conduct%20for%20Health%20Professionals%20V1%20202613351.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"DU-009","edition":"dubai","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Accurate documentation","stem":"After administering prescribed analgesia in Dubai, which record best supports safe continuing care?","options":[{"label":"A","text":"Record that all routine care was completed during the shift."},{"label":"B","text":"Record the medicine only if pain remains severe."},{"label":"C","text":"Record the intended response before reassessment occurs."},{"label":"D","text":"Record the assessment, medicine given, time, and reassessed response."}],"key":"D","answerText":"Record the assessment, medicine given, time, and reassessed response.","rationale":"The record should show what was done and how the patient responded. Intended outcomes must not be recorded as observed facts.","misconceptions":{"A":"A broad completion statement omits important clinical details.","B":"Effective treatment still requires a record.","C":"An expected response is not a measured outcome."},"pearl":"DHA practice: Record the assessment, medicine given, time, and reassessed response.","trap":"A broad completion statement omits important clinical details.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Standards for Code of Ethics and Professional Conduct for Health Professionals, DHA/HRS/HPSD/ST-66, issue 1","section":"9.3.1 and 9.3.3, p.24","url":"https://dha.gov.ae/uploads/012026/Standards%20for%20Code%20of%20Ethics%20and%20Professional%20Conduct%20for%20Health%20Professionals%20V1%20202613351.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"DU-010","edition":"dubai","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Clinical handover","stem":"A patient in Dubai needs more oxygen than earlier in the shift. Which handover is most appropriate?","options":[{"label":"A","text":"List completed routine tasks before ending the handover."},{"label":"B","text":"Describe the change, current observations, actions taken, and required follow-up."},{"label":"C","text":"Describe the admission diagnosis and leave changes in the chart."},{"label":"D","text":"Report that the patient is comfortable without mentioning oxygen."}],"key":"B","answerText":"Describe the change, current observations, actions taken, and required follow-up.","rationale":"A new oxygen requirement is a relevant change in condition. The receiving team needs the current situation and outstanding actions.","misconceptions":{"A":"Task completion does not explain the new clinical risk.","C":"The chart does not replace communication of a significant change.","D":"Comfort does not establish stable oxygenation."},"pearl":"DHA practice: Describe the change, current observations, actions taken, and required follow-up.","trap":"The chart does not replace communication of a significant change.","difficulty":"Medium","judgment":"Take Action","hyp":85,"population":"Adult","setting":"Inpatient ward","source":{"title":"Standards for Code of Ethics and Professional Conduct for Health Professionals, DHA/HRS/HPSD/ST-66, issue 1","section":"12.3.1–12.3.2, p.35","url":"https://dha.gov.ae/uploads/012026/Standards%20for%20Code%20of%20Ethics%20and%20Professional%20Conduct%20for%20Health%20Professionals%20V1%20202613351.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}}],"qatar":[{"id":"QA-001","edition":"qatar","kind":"practice-setting","replaces":null,"domain":"Nursing Management and Leadership","subdomain":"Scope and competence","stem":"In a Qatar ward, an RGN is asked to perform an unfamiliar elective procedure. The nurse has no assessed competence in it. What is the best response?","options":[{"label":"A","text":"Proceed while a colleague gives instructions by telephone."},{"label":"B","text":"Perform it because a prescriber has requested it."},{"label":"C","text":"Ask the patient to accept the additional risk."},{"label":"D","text":"Explain the competence gap and arrange a suitably qualified practitioner."}],"key":"D","answerText":"Explain the competence gap and arrange a suitably qualified practitioner.","rationale":"The request does not establish competence. Arranging qualified help protects the patient without abandoning care.","misconceptions":{"A":"Remote instructions do not establish assessed competence.","B":"An order does not extend the nurse’s competence.","C":"Patient agreement cannot replace professional competence."},"pearl":"Qatar RGN practice: Explain the competence gap and arrange a suitably qualified practitioner.","trap":"Remote instructions do not establish assessed competence.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Nursing Regulations in the State of Qatar — §2.2 Registered General Nurses Scope of Practice","section":"RGN 1.1.2–1.1.3, p.15","url":"https://dhp.moph.gov.qa/en/Documents/Nursing%20Regulations%20in%20the%20State%20of%20Qatar.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"QA-002","edition":"qatar","kind":"practice-setting","replaces":null,"domain":"Nursing Management and Leadership","subdomain":"Delegation checks","stem":"A Qatar RGN plans to delegate a stable patient’s scheduled care task. What must be checked before choosing the team member?","options":[{"label":"A","text":"Choose the worker who agrees to accept responsibility."},{"label":"B","text":"Confirm that the task fits the worker’s authorized role and demonstrated competence."},{"label":"C","text":"Choose the worker who has the lightest workload."},{"label":"D","text":"Use the worker who has observed the task most often."}],"key":"B","answerText":"Confirm that the task fits the worker’s authorized role and demonstrated competence.","rationale":"Willingness and availability do not establish authority or ability. Delegation must fit the person and the task.","misconceptions":{"A":"Agreement does not create authority to perform a task.","C":"Workload matters only after role and ability are established.","D":"Observation alone does not establish competence."},"pearl":"Qatar RGN practice: Confirm that the task fits the worker’s authorized role and demonstrated competence.","trap":"Workload matters only after role and ability are established.","difficulty":"Medium","judgment":"Generate Solutions","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Nursing Regulations in the State of Qatar — §2.2 Registered General Nurses Scope of Practice","section":"RGN 3.3.1, p.18","url":"https://dhp.moph.gov.qa/en/Documents/Nursing%20Regulations%20in%20the%20State%20of%20Qatar.pdf","accessed":"2026-10-25"},"review":{"panel":"FIXED","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Exact replacements applied: judgment. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"QA-003","edition":"qatar","kind":"practice-setting","replaces":null,"domain":"Nursing Management and Leadership","subdomain":"Delegation follow-up","stem":"In Qatar, an RGN has delegated care to a competent colleague. Which action best meets the RGN’s ongoing responsibility?","options":[{"label":"A","text":"Remove the task from handover because it was delegated."},{"label":"B","text":"Check the reported outcome and provide supervision matched to the task."},{"label":"C","text":"Review the outcome only if the patient makes a complaint."},{"label":"D","text":"Assume completion because the worker accepted the task."}],"key":"B","answerText":"Check the reported outcome and provide supervision matched to the task.","rationale":"Delegation does not end the need for oversight. Outcome review helps identify care that needs adjustment.","misconceptions":{"A":"Delegated care can remain relevant at handover.","C":"Waiting for a complaint misses earlier signs of incomplete care.","D":"Acceptance is not evidence of a safe outcome."},"pearl":"Qatar RGN practice: Check the reported outcome and provide supervision matched to the task.","trap":"Waiting for a complaint misses earlier signs of incomplete care.","difficulty":"Medium","judgment":"Evaluate Outcomes","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Nursing Regulations in the State of Qatar — §2.2 Registered General Nurses Scope of Practice","section":"RGN 3.3.2–3.3.3, p.18","url":"https://dhp.moph.gov.qa/en/Documents/Nursing%20Regulations%20in%20the%20State%20of%20Qatar.pdf","accessed":"2026-10-25"},"review":{"panel":"FIXED","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Exact replacements applied: judgment. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"QA-004","edition":"qatar","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Consent and understanding","stem":"Before an elective procedure in Qatar, a patient says, “I signed because I thought this was a blood test.” What should the nurse do first?","options":[{"label":"A","text":"Ask a relative to confirm that the procedure is acceptable."},{"label":"B","text":"Repeat the procedure name and request another signature."},{"label":"C","text":"Pause preparation and arrange an understandable explanation before consent is confirmed."},{"label":"D","text":"Continue because the signed form is already in the record."}],"key":"C","answerText":"Pause preparation and arrange an understandable explanation before consent is confirmed.","rationale":"A signature alone does not show informed agreement. The misunderstanding must be addressed before the elective procedure proceeds.","misconceptions":{"A":"A relative’s agreement does not replace the capable patient’s consent.","B":"Repeating a name does not explain the procedure.","D":"A form does not resolve the stated misunderstanding."},"pearl":"Qatar RGN practice: Pause preparation and arrange an understandable explanation before consent is confirmed.","trap":"A form does not resolve the stated misunderstanding.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Nursing Regulations in the State of Qatar — §2.2 Registered General Nurses Scope of Practice","section":"RGN 1.2.5, p.15","url":"https://dhp.moph.gov.qa/en/Documents/Nursing%20Regulations%20in%20the%20State%20of%20Qatar.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"QA-005","edition":"qatar","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Patient advocacy","stem":"A capable adult in Qatar wants the clinician to explain another treatment option. A relative asks the nurse to keep to the original plan. What is the best response?","options":[{"label":"A","text":"Support the patient in discussing options with the treating clinician."},{"label":"B","text":"Ask the family to decide which option will be discussed."},{"label":"C","text":"Discourage further questions because a plan is documented."},{"label":"D","text":"Ask the patient to decide without further information."}],"key":"A","answerText":"Support the patient in discussing options with the treating clinician.","rationale":"Care should support the patient’s informed participation. Family involvement should not prevent the patient from receiving information.","misconceptions":{"B":"Family preference does not displace a capable adult’s voice.","C":"Documentation does not end the right to ask questions.","D":"A meaningful choice requires adequate information."},"pearl":"Qatar RGN practice: Support the patient in discussing options with the treating clinician.","trap":"Family preference does not displace a capable adult’s voice.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Nursing Regulations in the State of Qatar — §2.2 Registered General Nurses Scope of Practice","section":"RGN 1.2.3 and 1.2.5, p.15","url":"https://dhp.moph.gov.qa/en/Documents/Nursing%20Regulations%20in%20the%20State%20of%20Qatar.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"QA-006","edition":"qatar","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Confidentiality","stem":"On a Qatar ward, a visitor asks for an adult patient’s laboratory results. The nurse has not established permission to share them. What is the best response?","options":[{"label":"A","text":"Verify identity and the authority to receive information before disclosure."},{"label":"B","text":"Share only the abnormal results to limit disclosure."},{"label":"C","text":"Give the results if the person knows the patient’s birth date."},{"label":"D","text":"Ask another visitor to confirm the relationship."}],"key":"A","answerText":"Verify identity and the authority to receive information before disclosure.","rationale":"The request alone does not authorize disclosure. Identity and a valid basis for access must both be established.","misconceptions":{"B":"Selected results are still confidential information.","C":"A known personal detail does not establish authority.","D":"Another visitor cannot establish consent or legal authority."},"pearl":"Qatar RGN practice: Verify identity and the authority to receive information before disclosure.","trap":"Selected results are still confidential information.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Nursing Regulations in the State of Qatar — §2.2 Registered General Nurses Scope of Practice","section":"RGN 1.2.4, p.15","url":"https://dhp.moph.gov.qa/en/Documents/Nursing%20Regulations%20in%20the%20State%20of%20Qatar.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"QA-007","edition":"qatar","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Privacy and dignity","stem":"During a bedside discussion in Qatar, nearby visitors can hear sensitive details. The patient is stable. What should the nurse do?","options":[{"label":"A","text":"Omit the patient’s name but discuss the full history."},{"label":"B","text":"Move the conversation to a private setting with the patient’s agreement."},{"label":"C","text":"Continue quietly while using the patient’s room number."},{"label":"D","text":"Ask visitors to ignore the conversation and continue."}],"key":"B","answerText":"Move the conversation to a private setting with the patient’s agreement.","rationale":"Avoidable exposure of personal information should be reduced. Omitting a name does not make an identifiable bedside conversation private.","misconceptions":{"A":"The surroundings can identify the person without a name.","C":"Room context can still identify the patient.","D":"A request to ignore information does not protect privacy."},"pearl":"Qatar RGN practice: Move the conversation to a private setting with the patient’s agreement.","trap":"Room context can still identify the patient.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Nursing Regulations in the State of Qatar — §2.2 Registered General Nurses Scope of Practice","section":"RGN 1.2.4 and 1.2.6, p.15","url":"https://dhp.moph.gov.qa/en/Documents/Nursing%20Regulations%20in%20the%20State%20of%20Qatar.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"QA-008","edition":"qatar","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Respectful cultural care","stem":"A stable patient in Qatar requests a same-gender practitioner for intimate care. What should the nurse do first?","options":[{"label":"A","text":"Assume the request applies to every future procedure."},{"label":"B","text":"Ask a family member to persuade the patient to withdraw it."},{"label":"C","text":"Cancel all planned care until a same-gender team is available."},{"label":"D","text":"Explore the preference and arrange suitable care where feasible without delaying urgent needs."}],"key":"D","answerText":"Explore the preference and arrange suitable care where feasible without delaying urgent needs.","rationale":"Preferences should be discussed individually and respected where feasible. The nurse must also account for the urgency of care.","misconceptions":{"A":"An individual preference must not be generalized without discussion.","B":"Pressure from family can undermine the patient’s choice.","C":"A blanket cancellation may cause unnecessary delay."},"pearl":"Qatar RGN practice: Explore the preference and arrange suitable care where feasible without delaying urgent needs.","trap":"An individual preference must not be generalized without discussion.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Nursing Regulations in the State of Qatar — §2.2 Registered General Nurses Scope of Practice","section":"RGN 1.2.6–1.2.7, p.15","url":"https://dhp.moph.gov.qa/en/Documents/Nursing%20Regulations%20in%20the%20State%20of%20Qatar.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"QA-009","edition":"qatar","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Accurate documentation","stem":"After giving prescribed pain relief in Qatar, which entry best supports continuing care?","options":[{"label":"A","text":"Record the intended response before reassessment occurs."},{"label":"B","text":"Record the assessment, medicine given, time, and reassessed response."},{"label":"C","text":"Record that all routine care was completed during the shift."},{"label":"D","text":"Record the medicine only if pain remains severe."}],"key":"B","answerText":"Record the assessment, medicine given, time, and reassessed response.","rationale":"The record should show what was done and how the patient responded. Intended outcomes must not be recorded as observed facts.","misconceptions":{"A":"An expected response is not a measured outcome.","C":"A broad completion statement omits important clinical details.","D":"Effective treatment still requires a record."},"pearl":"Qatar RGN practice: Record the assessment, medicine given, time, and reassessed response.","trap":"A broad completion statement omits important clinical details.","difficulty":"Medium","judgment":"Take Action","hyp":75,"population":"Adult","setting":"Inpatient ward","source":{"title":"Nursing Regulations in the State of Qatar — §2.2 Registered General Nurses Scope of Practice","section":"RGN 2.1.12–2.1.13, p.17","url":"https://dhp.moph.gov.qa/en/Documents/Nursing%20Regulations%20in%20the%20State%20of%20Qatar.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}},{"id":"QA-010","edition":"qatar","kind":"practice-setting","replaces":null,"domain":"Nursing Fundamentals","subdomain":"Clinical handover","stem":"A Qatar ward nurse hands over a patient with a new oxygen requirement. Which information is most important to communicate?","options":[{"label":"A","text":"Describe the change, current observations, actions taken, and required follow-up."},{"label":"B","text":"Describe the admission diagnosis and leave changes in the chart."},{"label":"C","text":"Report that the patient is comfortable without mentioning oxygen."},{"label":"D","text":"List completed routine tasks before ending the handover."}],"key":"A","answerText":"Describe the change, current observations, actions taken, and required follow-up.","rationale":"A new oxygen requirement is a relevant change in condition. The receiving team needs the current situation and outstanding actions.","misconceptions":{"B":"The chart does not replace communication of a significant change.","C":"Comfort does not establish stable oxygenation.","D":"Task completion does not explain the new clinical risk."},"pearl":"Qatar RGN practice: Describe the change, current observations, actions taken, and required follow-up.","trap":"The chart does not replace communication of a significant change.","difficulty":"Medium","judgment":"Take Action","hyp":85,"population":"Adult","setting":"Inpatient ward","source":{"title":"Nursing Regulations in the State of Qatar — §2.2 Registered General Nurses Scope of Practice","section":"RGN 2.2.3, p.17","url":"https://dhp.moph.gov.qa/en/Documents/Nursing%20Regulations%20in%20the%20State%20of%20Qatar.pdf","accessed":"2026-10-25"},"review":{"panel":"PASS","notes":"AI pre-review — not a licensed clinical sign-off. Final approval requires a real licensed nurse reviewer. Still pending review by a real licensed nurse; AI PASS does not authorize publication."}}]},"order":["saudi","qatar","dubai","abudhabi"],"editions":{"saudi":{"profile":"snle","short":"SNLE","tab":"Saudi","accent":"#087d72","regulatorShort":"SCFHS","region":"Saudi Arabia","theme":"Palm & Teal","tiles":[{"k":"Questions","v":"200","s":"ok","n":"Two blocks of 100"},{"k":"Time","v":"4 hours","s":"ok","n":"2 × 120 minutes, with a scheduled break"},{"k":"Pass mark","v":"500","s":"ok","n":"Scaled score, 200–800"},{"k":"Attempts","v":"See guide","s":"check","n":"SCFHS sources differ"}],"intro":"200 multiple-choice questions in two blocks of 100, each 120 minutes, with a scheduled break. SCFHS reports a scaled score from 200 to 800; 500 is the pass mark.","mix":"SCFHS publishes how many questions come from each area. Practice sets in this studio follow that split.","fullName":"Saudi Nursing Licensure Examination","regulator":"Saudi Commission for Health Specialties (SCFHS)","questions":200,"minutes":240,"sources":[{"label":"SCFHS Applicant Guide","url":"https://scfhs.org.sa/sites/default/files/2025-09/SNLE%20Applicant%20Guide%20.pdf"}],"domains":[{"label":"Nursing Fundamentals","count":40},{"label":"Adult Nursing","count":80},{"label":"Maternal–Child Nursing","count":60},{"label":"Management and Leadership","count":20}],"facts":"200 questions · 4 hours","notes":{"retake":"SCFHS sources differ: the applicant guide describes up to four attempts a year, while the SCFHS dates page describes three attempts in an initial cycle with renewal provisions after a year. This is not a lifetime maximum. Confirm with SCFHS before relying on either."}},"qatar":{"short":"DHP RGN","tab":"Qatar","accent":"#8a1538","regulatorShort":"DHP","region":"Qatar","theme":"Pearl & Maroon","tiles":[{"k":"Questions","v":"150","s":"ok","n":"Multiple choice"},{"k":"Time","v":"3 hours","s":"check","n":"An older DHP document says 3½ hours"},{"k":"Pass mark","v":"50%","s":"ok","n":"Published minimum"},{"k":"Attempts","v":"Up to 5","s":"check","n":"DHP policy v04"}],"intro":"150 multiple-choice questions. The current DHP exam page says 3 hours; an older DHP blueprint document says 3½ hours, so check the time on your booking confirmation.","mix":"DHP publishes how many questions come from each area. Practice sets in this studio follow that split.","fullName":"Qatar Registered General Nurse Qualifying Examination","regulator":"Department of Healthcare Professions (DHP), Ministry of Public Health","questions":150,"minutes":180,"sources":[{"label":"Current DHP qualifying examinations","url":"https://dhp.moph.gov.qa/en/Pages/QualifyingExamination.aspx"},{"label":"Official RN blueprint and reference PDF","url":"https://dhp.moph.gov.qa/en/Documents/NurseAndMidwiferyBlueprintAndReference.pdf"}],"domains":[{"label":"Nursing Fundamentals","count":30},{"label":"Adult Nursing","count":61},{"label":"Maternal–Child Nursing","count":44},{"label":"Unit Management and Leadership","count":15}],"facts":"150 questions · 3 hours","notes":{"retake":"DHP policy (v04) and the qualifying-examination page describe five attempts. A three-attempt line sits under physician specialties and does not clearly apply to nurses. Effective dates are not stated; not confirmed in writing by DHP."}},"dubai":{"short":"DHA RN","tab":"Dubai","accent":"#9a6514","regulatorShort":"DHA","region":"Dubai","theme":"Desert Gold","tiles":[{"k":"Questions","v":"150","s":"ok","n":"Multiple choice"},{"k":"Time","v":"3 hours","s":"ok","n":"Includes registration and introduction"},{"k":"Pass mark","v":"50%","s":"ok","n":"Result shown as pass or fail"},{"k":"Attempts","v":"3 across the UAE","s":"check","n":"A 4th only with permission"}],"intro":"150 multiple-choice questions in 3 hours. The 3 hours includes registration and a short introduction, so your answering time is a little less.","mix":"DHA does not publish how many questions come from each area. To keep practice fair, this studio spreads questions across all four areas using its own mix, shown below. It is not the DHA split.","fullName":"Dubai DHA Registered Nurse Assessment","regulator":"Dubai Health Authority (DHA)","questions":150,"minutes":180,"sources":[{"label":"Official DHA CBT assessment guideline","url":"https://dha.gov.ae/sheryan/wps/contenthandler/%21ut/p/digest%21L_negPqVWa2FDiru8UDKPw/war/SheryanHomeThemeStatic/themes/Portal8.5/docs/Final_Online_Exam_Guideline_CBT.pdf"},{"label":"Official DHA Get Registered","url":"https://www.dha.gov.ae/sheryan/wps/portal/home/services-professional/service-description?CATALOGUE_TYPE=PROFESSIONAL&scode=NRG"}],"domains":[{"label":"Nursing Fundamentals","count":null},{"label":"Adult Nursing","count":null},{"label":"Maternal–Child Nursing","count":null},{"label":"Unit Management and Leadership","count":null}],"facts":"150 questions · 3 hours","notes":{"retake":"General DHA licensing rules apply: three attempts across UAE authorities, a fourth only with permission, and a two-year block after the third failure before new attempts. Sources differ on details; confirm with DHA."}},"abudhabi":{"short":"DOH RN","tab":"Abu Dhabi","accent":"#1f5f8b","regulatorShort":"DOH","region":"Abu Dhabi","theme":"Gulf Sea","tiles":[{"k":"Questions","v":"150","s":"ok","n":"Multiple choice"},{"k":"Time","v":"3 hours","s":"ok","n":"DOH nursing circular, 2024"},{"k":"Pass mark","v":"Not published","s":"none","n":"DOH reports pass or fail only"},{"k":"Attempts","v":"3 across the UAE","s":"check","n":"A final attempt may be approved"}],"intro":"150 multiple-choice questions in 3 hours (DOH nursing licensing circular, 2024). DOH reports a pass or fail result and does not publish its pass mark.","mix":"DOH does not publish how many questions come from each area. To keep practice fair, this studio spreads questions across all four areas using its own mix, shown below. It is not the DOH split.","fullName":"Abu Dhabi Department of Health Registered Nurse","regulator":"Department of Health – Abu Dhabi (DOH)","questions":150,"minutes":180,"sources":[{"label":"DOH 2024 Nursing Licensing Circular (RN CBT)","url":"https://www.doh.gov.ae/-/media/Feature/Resources/Circulars/2024/151--2024.ashx"},{"label":"DOH professional qualification requirements","url":"https://www.doh.gov.ae/en/pqr"},{"label":"UAE common PQR guidance","url":"https://mohap.gov.ae/en/w/evaluation-of-health-professional"}],"domains":[{"label":"Nursing Fundamentals","count":null},{"label":"Adult Nursing","count":null},{"label":"Maternal–Child Nursing","count":null},{"label":"Management and Professional Practice","count":null}],"facts":"150 questions · 3 hours","notes":{"retake":"UAE-wide rules allow three attempts across authorities, with a possible final attempt subject to approval. Confirm with DOH."}}},"policy":"Original practice material written for this studio. It is not official exam content, is not endorsed by SCFHS, DHP, DHA or DOH, and does not predict your result. No recalled exam questions are used.","disclaimer":"Original practice material, not official exam questions. Not endorsed by SCFHS, DHP, DHA or DOH.","checked":"23 October 2026","sb":{"url":"https://ujeofxfbwivjmgrxqdcl.supabase.co","key":"sb_publishable_ie1qqB5QnaqUZPitNPfQCg__M46e7JL"}};